    lowSupport: "#6E6560",
    neutral: "#1A1714",
    background: "#f5f5f5"
  },
  // Line equations: y = intercept + slope * x
  // Lines cross where: highIntercept + highSlope*x = lowIntercept + lowSlope*x
  lines: {
    high: { intercept: 65, slope: -0.4 },
    low: { intercept: 25, slope: 0.4 }
  },
